[package]
name = "indicators"
version = "0.1.0"
edition = "2021"
description = "Pure-std Rust port of the C++ `indicators.hpp` progress-bar header"

# Library code lives in modules under src/; see src/lib.rs.
[lib]
name = "indicators"
path = "src/lib.rs"

# Entry test file kept in the package root, so that a bare `rustc test2.rs`
# also builds it (the module tree is pulled in with #[path] attributes).
[[bin]]
name = "test2"
path = "test2.rs"

[dependencies]
--- lib.rs ---
//! Pure-`std` re-implementation of the small `indicators.hpp` C++ header used by
//! the test programs in this dataset.
//!
//! The crate deliberately mirrors the C++ observable behaviour, including the
//! `float`/`double` arithmetic widths and the `std::ostream` number formatting,
//! so that output is byte-for-byte identical to the C++ binary.

pub mod indicators;

pub use crate::indicators::{Percentage, ProgressBar};

